    $("ucl-credit-rule-form").addEventListener("submit",async e=>{e.preventDefault();const msg=$("ucl-rule-msg"),payload={service_id:$("ucl-rule-service").value,wallet_id:$("ucl-rule-wallet").value,credit_amount:Number($("ucl-rule-amount").value),is_active:true,updated_by:uid,updated_at:new Date().toISOString()};if(!payload.service_id||!payload.wallet_id||!Number.isFinite(payload.credit_amount)||payload.credit_amount<=0){msg.textContent="Select service, wallet and a positive credit amount.";return;}const r=await supabase.from("ucl_service_credit_rules").upsert(payload,{onConflict:"service_id"});msg.textContent=r.error?r.error.message:"Service-wise UCL credit rule saved.";if(!r.error)await renderOperations(view,ctx);});
